<section class="mt-7"><div class="flex items-end justify-between"><div><p class="text-xs font-bold uppercase tracking-wider text-mint">Individual access</p><h2 class="text-xl font-extrabold"><?= esc(trim($target['first_name'].' '.$target['last_name'])) ?></h2><p class="text-sm text-[#78908c]"><?= esc($target['email']) ?> · <?= esc(ucwords(str_replace('_',' ',$target['account_type']))) ?></p></div><a href="<?= portal_url('accounts') ?>" class="btn shadow-soft">Back</a></div><form method="post" class="mt-6 grid gap-5 xl:grid-cols-[1.6fr_1fr]"><?= csrf_field() ?><section class="card p-6"><div class="mb-5"><h3 class="font-extrabold">Permission overrides</h3><p class="text-sm text-[#78908c]">Explicit deny overrides role defaults. Inherit uses the assigned role preset.</p></div><?php $grouped=[];foreach($definitions as$d)$grouped[$d['module']][]=$d;foreach($grouped as$module=>$items): ?><div class="mb-6"><h4 class="mb-2 text-xs font-extrabold uppercase tracking-wider text-sea"><?= esc($module) ?></h4><div class="divide-y divide-[#dbeae7]"><?php foreach($items as$d): ?><div class="flex items-center justify-between gap-4 py-2"><span class="text-sm"><?= esc($d['label']) ?><?= $d['sensitive']?' · Sensitive':'' ?></span><select name="permissions[<?= esc($d['permission_key']) ?>]" class="field max-w-32 py-2 text-xs"><?php foreach(['inherit','allow','deny'] as$s): ?><option value="<?= $s ?>" <?= ($states[$d['permission_key']]??'inherit')===$s?'selected':'' ?>><?= ucfirst($s) ?></option><?php endforeach ?></select></div><?php endforeach ?></div></div><?php endforeach ?></section><aside class="card h-fit p-6"><h3 class="font-extrabold">Workspace access</h3><p class="mt-1 text-sm text-[#78908c]">Only selected customer workspaces are accessible.</p><div class="mt-4 space-y-3"><?php foreach($workspaces as$w): ?><label class="flex items-center gap-3 rounded-xl bg-[#e7f2ef] p-3 text-sm font-bold"><input type="checkbox" name="workspace_ids[]" value="<?= $w['id'] ?>" <?= in_array($w['id'],$assigned)?'checked':'' ?> class="accent-[#44b89d]"><?= esc($w['company_name']?:$w['name']) ?></label><?php endforeach ?></div><button class="btn btn-primary mt-5 w-full justify-center">Save access</button></aside></form></section>
